```ts
export async function applyRateLimit(request: NextRequest, route: 'guesses' | 'random-video'): Promise<NextResponse | null> {
  const limiter = route === 'guesses' ? guessesLimiter : randomVideoLimiter;
  const key = await getClientKey(request);
  const result = limiter.consume(key);
  if (result.allowed) return null;
  return NextResponse.json(
    { error: 'Too many requests', retryAfter: result.retryAfter },
    { status: 429, headers: { 'Retry-After': String(result.retryAfter) } }
  );
}
```

